import { VMError } from "../../runtime/errors.js";
import { MANIFEST_INVALID } from "../../wasm/decode-support.js";
import type { ResolvedManifest } from "../../wasm/manifest-types.js";
import { servedName } from "./release.js";

/** First line of a generated file; staging refuses to overwrite a file that lacks it. */
export const GENERATED_MARKER = "// @generated by `oxidevm wasm stage`. Do not edit: change oxidevm.modules.json and run the command again.";

/** What the generated handle of one module needs. */
export interface HandleSpec {
  readonly manifest: ResolvedManifest;
  /** The release id: it names the staged directory and goes into the pins. */
  readonly release: string;
  /** The staged files of the release (the adapter and every artifact). */
  readonly files: readonly { readonly name: string; readonly sha256: string; readonly bytes: number }[];
  /** Directory of the staged files, relative to the generated file and written with `/`. */
  readonly directory: string;
}

const RESERVED = new Set(["arguments", "eval", "break", "case", "catch", "class", "const", "continue", "debugger", "default", "delete", "do", "else", "enum", "export", "extends", "false", "finally", "for", "function", "if", "import", "in", "instanceof", "new", "null", "return", "super", "switch", "this", "throw", "true", "try", "typeof", "var", "void", "while", "with", "yield", "let", "static", "implements", "interface", "package", "private", "protected", "public", "await", "async", "of", "moduleHandle"]);

/** `my-tool` becomes `myTool`; the module id grammar guarantees a valid identifier except for reserved words. */
export function moduleIdentifier(id: string): string {
  const name = id.replace(/-([a-z0-9])/gu, (_match, character: string) => character.toUpperCase());
  if (!/^[a-z][A-Za-z0-9]*$/u.test(name) || RESERVED.has(name)) throw new VMError("INVALID_ARGUMENT", `module id ${id} cannot be exported as a JavaScript name`, { reason: MANIFEST_INVALID });
  return name;
}

function pin(file: HandleSpec["files"][number], directory: string): string {
  return `{ url: new URL(${JSON.stringify(`${directory}/${servedName(file.name)}`)}, import.meta.url).href, sha256: ${JSON.stringify(file.sha256)}, bytes: ${String(file.bytes)} }`;
}

/**
 * The text of `src/oxidevm.modules.generated.ts`: one typed handle per module, whose manifest literal carries the
 * exact options and endpoints and whose pins point at the staged files by URLs a bundler can resolve.
 */
export function renderHandles(specs: readonly HandleSpec[]): string {
  const sorted = [...specs].sort((left, right) => left.manifest.id < right.manifest.id ? -1 : 1);
  const names = sorted.map(spec => moduleIdentifier(spec.manifest.id));
  if (new Set(names).size !== names.length) throw new VMError("INVALID_ARGUMENT", "two module ids map to the same JavaScript name", { reason: MANIFEST_INVALID });
  const handles = sorted.map((spec, index) => {
    const adapter = spec.files.find(file => file.name === "adapter.mjs");
    if (adapter === undefined) throw new VMError("INVALID_ARGUMENT", `${spec.manifest.id} has no adapter.mjs`, { reason: MANIFEST_INVALID });
    const artifacts = spec.files.filter(file => file.name !== "adapter.mjs").map(file => `    ${JSON.stringify(file.name)}: ${pin(file, spec.directory)},`);
    return [
      `export const ${names[index] ?? ""} = moduleHandle(${JSON.stringify(spec.manifest, null, 2)}, {`,
      `  release: ${JSON.stringify(spec.release)},`,
      `  adapter: ${pin(adapter, spec.directory)},`,
      `  artifacts: {`,
      ...artifacts,
      `  },`,
      `});`,
    ].join("\n");
  });
  return `${GENERATED_MARKER}\nimport { moduleHandle } from "@oxidevm/sdk/wasm";\n\n${handles.join("\n\n")}${handles.length === 0 ? "export {};" : ""}\n`;
}
